function mapAttribution(){return `<p class="map-attribution"><a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener noreferrer">Natural Earth</a> · <a href="https://data.linz.govt.nz/layer/51153-nz-coastlines-and-islands-polygons-topo-150k/" target="_blank" rel="noopener noreferrer">LINZ Data Service</a> / <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a> · ${lang==='zh'?'投影与绘图经调整':'Reprojected and styled'}</p>`}
function lineKey(mode){return ['ferry','rail'].includes(mode)?'transit':mode}
function mapLegend(modes=['walk','cycle','drive','transit'],detailed=false){return `<div class="map-legend">${modes.map(m=>`<span><svg viewBox="0 0 42 12" aria-hidden="true"><path class="map-line map-line-${m}" d="M2 6 Q15 5 23 6 T40 6"/></svg>${t(detailed&&m==='transit'?'bus':m)}</span>`).join('')}</div>`}
function mapProjection(points,width=900,height=560,pad=85){const avg=points.reduce((a,p)=>a+p.lat,0)/points.length,cos=Math.cos(avg*Math.PI/180);let xs=points.map(p=>p.lon*cos),ys=points.map(p=>-p.lat),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);const spanX=Math.max(maxX-minX,.015),spanY=Math.max(maxY-minY,.015),scale=Math.min((width-pad*2)/spanX,(height-pad*2)/spanY),midX=(minX+maxX)/2,midY=(minY+maxY)/2;return p=>[width/2+(p.lon*cos-midX)*scale,height/2+(-p.lat-midY)*scale]}
function coastlinePaths(project){const polygons=nzCoastline.geometry.type==='MultiPolygon'?nzCoastline.geometry.coordinates:[nzCoastline.geometry.coordinates];return polygons.map(poly=>poly.map(ring=>ring.map((p,i)=>{const [x,y]=project({lon:p[0],lat:p[1]});return(i?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)}).join('')+'Z').join('')).join('')}
function terrainMarkup(prefix,w=900,h=560){return `<defs><pattern id="${prefix}-grid" width="45" height="45" patternUnits="userSpaceOnUse"><path d="M45 0H0V45" fill="none" stroke="#566c4c" stroke-opacity=".055"/></pattern><clipPath id="${prefix}-clip"><rect width="${w}" height="${h}"/></clipPath></defs><rect width="${w}" height="${h}" fill="#dce9e6"/><rect width="${w}" height="${h}" fill="url(#${prefix}-grid)"/>`}

function routePath(a,b,index,returning=false){const dx=b[0]-a[0],dy=b[1]-a[1],length=Math.hypot(dx,dy)||1,offset=returning?15:Math.min(9,length*.045)*(index%2?1:-1);return `M${a[0].toFixed(1)} ${a[1].toFixed(1)} Q${((a[0]+b[0])/2-dy/length*offset).toFixed(1)} ${((a[1]+b[1])/2+dx/length*offset).toFixed(1)} ${b[0].toFixed(1)} ${b[1].toFixed(1)}`}
function mapMarkerLayout(points,xy,width,height,gap){const out=Object.fromEntries(points.map(p=>[p.id,[...xy[p.id]]]));for(let pass=0;pass<45;pass++){for(let i=0;i<points.length;i++)for(let j=i+1;j<points.length;j++){const a=out[points[i].id],b=out[points[j].id];let dx=b[0]-a[0],dy=b[1]-a[1],distance=Math.hypot(dx,dy);if(distance>=gap)continue;if(distance<.1){dx=1;dy=.5;distance=Math.hypot(dx,dy)}const push=(gap-distance)/2+.1,ux=dx/distance,uy=dy/distance;a[0]-=ux*push;a[1]-=uy*push;b[0]+=ux*push;b[1]+=uy*push;for(const p of [a,b]){p[0]=Math.min(width-35,Math.max(35,p[0]));p[1]=Math.min(height-45,Math.max(65,p[1]))}}}return out}
function renderRouteMap(r){const data=routeMapData[r.id],container=document.querySelector('#routeMap');if(!data||!container)return;const narrow=matchMedia('(max-width:750px)').matches,W=narrow?600:900,H=narrow?650:560,project=mapProjection(data.points,W,H,narrow?75:85),xy=Object.fromEntries(data.points.map(p=>[p.id,project(p)])),seen=new Set();const paths=data.legs.map((leg,i)=>{const reverse=seen.has(leg.to+'-'+leg.from);seen.add(leg.from+'-'+leg.to);const d=routePath(xy[leg.from],xy[leg.to],i,reverse);return `<g class="map-leg" data-leg-mode="${lineKey(leg.mode)}"><title>${escapeHtml(pick(leg.label))} · ${t(leg.mode)}</title><path d="${d}" class="map-line-under"/><path d="${d}" class="map-line map-line-${leg.mode}"/></g>`}).join('');const markers=mapMarkerLayout(data.points,xy,W,H,narrow?54:42);const stops=data.points.map((p,i)=>{const [x,y]=markers[p.id],[gx,gy]=xy[p.id];return `<path class="map-point-leader" d="M${gx} ${gy}L${x} ${y}"/><g class="map-stop${i===0?' selected':''}" data-stop="${i}" role="button" tabindex="0" aria-label="${escapeHtml((i+1)+'. '+pick(p.name))}" aria-pressed="${i===0}"><circle class="stop-halo" cx="${x}" cy="${y}" r="22"/><circle class="stop-circle" cx="${x}" cy="${y}" r="14"/><text x="${x}" y="${y+4.5}" text-anchor="middle">${String(i+1).padStart(2,'0')}</text></g>`}).join('');const modes=[...new Set(data.legs.map(l=>l.mode))];const detailModes=[...new Set(data.legs.map(l=>lineKey(l.mode)))];
container.innerHTML=`<div class="route-map-shell"><div class="map-paper"><div class="map-paper-header"><span>${lang==='zh'?'线路地图':'ROUTE MAP'}</span><span>${t(r.island==='north'?'northIsland':'southIsland')} · ${escapeHtml(pick(r.region))}</span></div><div class="map-canvas"><svg class="route-map-svg" viewBox="0 0 ${W} ${H}" role="group" aria-label="${escapeHtml(routeTitle(r)+' / '+t('mapDetails'))}">${terrainMarkup('route',W,H)}<g clip-path="url(#route-clip)"><path class="map-land" d="${coastlinePaths(project)}"/><g class="map-route-paths">${paths}</g>${stops}</g><g class="map-compass" transform="translate(${W-59} 55)"><text y="-19" text-anchor="middle">N</text><path d="M0-10 5 10 0 6-5 10Z"/></g><text class="map-region-label" x="29" y="${H-27}">${r.island==='north'?'TE IKA-A-MĀUI':'TE WAIPOUNAMU'} / AOTEAROA</text></svg><div class="map-controls"><button type="button" data-map-zoom="in" aria-label="${t('zoomIn')}">+</button><button type="button" data-map-zoom="out" aria-label="${t('zoomOut')}">−</button><button type="button" data-map-zoom="reset" aria-label="${t('resetMap')}">↺</button></div></div>${mapLegend(modes,true)}<div class="map-bottom-note">${t('mapShortNote')}</div>${mapAttribution()}</div><aside class="map-stops-panel"><p class="section-label">${t(r.mode)} / ${data.points.length} ${t('mapStop')}</p><h3>${lang==='zh'?'停留点':'Stops'}</h3><div class="map-stops-list">${data.points.map((p,i)=>{const next=data.legs.find(l=>l.from===p.id);return `<button class="map-stop-button${i===0?' selected':''}" type="button" data-stop="${i}" aria-pressed="${i===0}"><span class="map-stop-number">${String(i+1).padStart(2,'0')}</span><span><strong>${escapeHtml(pick(p.name))}</strong>${next?`<small>${t(next.mode==='transit'?'bus':next.mode)} · ${escapeHtml(pick(next.label))}</small>`:''}</span><span class="map-stop-arrow">↖</span></button>`}).join('')}</div><p class="map-selected-stop" role="status" aria-live="polite">01 / ${escapeHtml(pick(data.points[0].name))}</p></aside></div><div class="route-map-key"><span>${lang==='zh'?'线路图例':'Map legend'}</span>${mapLegend()}<span>${lang==='zh'?'节点与连线为示意，不能用于导航。':'Stops and lines are schematic and cannot be used for navigation.'}</span></div>`;
const select=i=>{container.querySelectorAll('[data-stop]').forEach(el=>{const active=Number(el.dataset.stop)===i;el.classList.toggle('selected',active);el.setAttribute('aria-pressed',String(active))});container.querySelector('.map-selected-stop').textContent=String(i+1).padStart(2,'0')+' / '+pick(data.points[i].name)};container.querySelectorAll('[data-stop]').forEach(el=>{el.addEventListener('click',()=>select(Number(el.dataset.stop)));if(el.tagName.toLowerCase()==='g')el.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();select(Number(el.dataset.stop))}})});let zoom=1;container.querySelectorAll('[data-map-zoom]').forEach(b=>b.addEventListener('click',()=>{zoom=b.dataset.mapZoom==='reset'?1:Math.min(2.25,Math.max(1,zoom+(b.dataset.mapZoom==='in'?.25:-.25)));const w=W/zoom,h=H/zoom;container.querySelector('.route-map-svg').setAttribute('viewBox',`${(W-w)/2} ${(H-h)/2} ${w} ${h}`)}));}
function renderAtlas(data){
 const c=document.querySelector('#routeAtlas');if(!c)return;
 const W=600,H=760,bounds=[{lon:166.2,lat:-47.4},{lon:178.8,lat:-34.0}],project=mapProjection(bounds,W,H,42);
 const starts=data.map(r=>{const d=routeMapData[r.id],p=d.points.find(p=>p.role==='start'||p.role==='start-finish')||d.points[0];return {...p,id:r.id}}),xy=Object.fromEntries(starts.map(p=>[p.id,project(p)])),markers=mapMarkerLayout(starts,xy,W,H,34);
 c.innerHTML=`<div class="atlas-paper"><div class="map-paper-header"><span>${lang==='zh'?'全国线路地图':'NEW ZEALAND ROUTE ATLAS'}</span><span>${data.length} ${t('routeCount')}</span></div><svg class="atlas-svg" viewBox="0 0 ${W} ${H}" role="group" aria-label="${lang==='zh'?'新西兰线路分布图':'New Zealand route atlas'}">${terrainMarkup('atlas',W,H)}<path class="map-land" d="${coastlinePaths(project)}"/>${data.map((r,i)=>{const d=routeMapData[r.id];return '<g>'+d.legs.map((l,j)=>{const a=d.points.find(p=>p.id===l.from),b=d.points.find(p=>p.id===l.to);return `<path class="map-line map-line-${l.mode}" d="${routePath(project(a),project(b),j)}"/>`}).join('')+'</g>'}).join('')}${data.map((r,i)=>{const p=markers[r.id],g=xy[r.id];return `<path class="map-point-leader" d="M${g[0]} ${g[1]}L${p[0]} ${p[1]}"/><a class="atlas-route" href="${routeUrl(r.id)}" aria-label="${escapeHtml(routeTitle(r)+' · '+t(r.mode))}"><title>${escapeHtml(routeTitle(r))} · ${t(r.mode)}</title><circle cx="${p[0]}" cy="${p[1]}" r="13"/><text x="${p[0]}" y="${p[1]+4}" text-anchor="middle">${i+1}</text></a>`}).join('')}<text class="atlas-island-name" x="440" y="180">${t('northIsland')}</text><text class="atlas-island-name" x="60" y="530">${t('southIsland')}</text></svg>${mapLegend()}<p class="map-bottom-note">${t('mapShortNote')}</p>${mapAttribution()}</div><div class="atlas-directory">${data.map((r,i)=>`<a href="${routeUrl(r.id)}"><span>${String(i+1).padStart(2,'0')}</span><strong>${escapeHtml(routeTitle(r))}</strong><small>${t(r.mode)}</small><span>↗</span></a>`).join('')}</div>`;
}

/* Optional route-map animation. It changes the presentation only; the map is
 * schematic and is not a measured track or a navigation tool. */
(() => {
  const SVG = 'http://www.w3.org/2000/svg';
  const icons = {
    walk:'<circle cx="16" cy="5" r="2"/><path d="m12 11 4-3 4 6 5 1M15 10l-3 9-6 8m7-11 6 5 2 7M12 12l-6 4"/>',
    cycle:'<circle cx="7" cy="22" r="6"/><circle cx="25" cy="22" r="6"/><path d="m7 22 7-12 11 12H7l-4-13h5m6 1h9m-1-5h4m-3 0 2 17"/>',
    drive:'<path d="m5 12 3-7h16l3 7 2 2v11H3V14l2-2Zm0 0h22M3 20h26M7 25v3m18-3v3M7 16h3m12 0h3"/>',
    transit:'<rect x="6" y="3" width="20" height="24" rx="4"/><path d="M6 17h20M9 27v3m14-3v3M10 22h2m8 0h2M10 7h12"/>',
    rail:'<rect x="7" y="3" width="18" height="22" rx="5"/><path d="M7 15h18M16 3v12M11 20h2m6 0h2M11 25l-5 5m15-5 5 5M9 28h14"/>',
    ferry:'<path d="m3 20 13-4 13 4-5 8H8l-5-8Zm7-2V8h12v10M16 8V3M10 12h12M3 29q4-3 7 0t7 0 7 0 6 0"/>'
  };
  let dispose = null;

  window.enhanceJourneyMap = function enhanceJourneyMap(route) {
    if (dispose) dispose();
    const container = document.querySelector('#routeMap');
    const data = typeof routeMapData !== 'undefined' && routeMapData[route.id];
    const svg = container?.querySelector('.route-map-svg');
    const routePaths = svg?.querySelector('.map-route-paths');
    const legs = routePaths ? [...routePaths.querySelectorAll('.map-leg')] : [];
    const canvas = container?.querySelector('.map-canvas');
    if (!data || !svg || !canvas || !legs.length || legs.length !== data.legs.length) return;

    const chinese = document.documentElement.lang.startsWith('zh');
    const copy = chinese
      ? {play:'沿路线走一遍', pause:'暂停', resume:'继续', replay:'重播', ready:'点击播放，查看路线示意。', done:'路线演示完成。', segment:(n,total)=>`第 ${n} 段 / 共 ${total} 段`}
      : {play:'Follow the route', pause:'Pause', resume:'Resume', replay:'Replay', ready:'Press play to follow the schematic route.', done:'Route preview complete.', segment:(n,total)=>`Section ${n} of ${total}`};

    const controls = document.createElement('div');
    controls.className = 'journey-motion';
    controls.innerHTML = '<button type="button" class="journey-motion-button"></button><span class="journey-motion-status" role="status" aria-live="polite"></span>';
    const button = controls.querySelector('button');
    const status = controls.querySelector('.journey-motion-status');
    button.textContent = copy.play;
    status.textContent = copy.ready;
    canvas.before(controls);

    const defs = document.createElementNS(SVG, 'defs');
    defs.setAttribute('class', 'journey-motion-defs');
    svg.prepend(defs);
    const serial = Math.random().toString(36).slice(2);
    const parts = legs.map((leg, i) => {
      const path = leg.querySelector('path.map-line');
      if (!path) return null;
      const mask = document.createElementNS(SVG, 'mask');
      const id = `journey-reveal-${serial}-${i}`;
      mask.setAttribute('id', id);
      mask.setAttribute('maskUnits', 'userSpaceOnUse');
      mask.setAttribute('x', '-50'); mask.setAttribute('y', '-50');
      mask.setAttribute('width', '1000'); mask.setAttribute('height', '660');
      const reveal = document.createElementNS(SVG, 'path');
      reveal.setAttribute('d', path.getAttribute('d'));
      reveal.setAttribute('fill', 'none'); reveal.setAttribute('stroke', 'white');
      reveal.setAttribute('stroke-width', '20'); reveal.setAttribute('stroke-linecap', 'round');
      mask.append(reveal); defs.append(mask);
      const length = Math.max(path.getTotalLength(), 0.01);
      reveal.style.strokeDasharray = `${length} ${length}`;
      return {leg, path, reveal, length, id};
    });
    if (parts.some(x => !x)) { controls.remove(); defs.remove(); return; }

    const marker = document.createElementNS(SVG, 'g');
    marker.setAttribute('class', 'journey-motion-marker');
    marker.setAttribute('aria-hidden', 'true');
    marker.innerHTML = '<circle r="17"></circle><svg class="journey-marker-icon" x="-14" y="-14" width="28" height="28" viewBox="0 0 32 32" fill="none" stroke="#244c39" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"></svg>';
    marker.style.display = 'none';
    routePaths.after(marker);

    const controller = new AbortController();
    const signal = controller.signal;
    const total = 8000;
    const fullLength = parts.reduce((sum, part) => sum + part.length, 0);
    let raf = 0, startedAt = null, elapsed = 0, playing = false, completed = false, previous = -1;
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)');

    function selectStop(id) {
      const index = data.points.findIndex(p => p.id === id);
      const stop = container.querySelector(`.map-stops-list [data-stop="${index}"]`);
      if (index >= 0 && stop) stop.click();
    }
    function showProgress(fraction) {
      let remaining = fullLength * Math.max(0, Math.min(1, fraction));
      let active = parts.length - 1, local = 1;
      for (let i = 0; i < parts.length; i++) {
        const part = parts[i];
        const progress = Math.max(0, Math.min(1, remaining / part.length));
        part.reveal.style.strokeDashoffset = String(part.length * (1 - progress));
        if (progress < 1 && active === parts.length - 1) { active = i; local = progress; }
        remaining -= part.length;
      }
      if (fraction >= 1) { active = parts.length - 1; local = 1; }
      if (previous !== active) {
        previous = active;
        status.textContent = copy.segment(active + 1, parts.length);
        selectStop(data.legs[active].from);
        marker.querySelector('.journey-marker-icon').innerHTML = icons[data.legs[active].mode] || icons.transit;
      }
      const point = parts[active].path.getPointAtLength(parts[active].length * local);
      marker.setAttribute('transform', `translate(${point.x} ${point.y})`);
    }
    function finish() {
      playing = false; completed = true; elapsed = total; raf = 0;
      parts.forEach(p => { p.reveal.style.strokeDashoffset = '0'; });
      marker.style.display = 'none';
      selectStop(data.legs[data.legs.length - 1].to);
      status.textContent = copy.done;
      button.textContent = copy.replay;
    }
    function tick(time) {
      if (!playing) return;
      if (startedAt === null) startedAt = time - elapsed;
      elapsed = Math.min(total, time - startedAt);
      showProgress(elapsed / total);
      if (elapsed >= total) finish();
      else raf = requestAnimationFrame(tick);
    }
    function start() {
      if (completed) { elapsed = 0; previous = -1; completed = false; }
      for (const part of parts) part.leg.setAttribute('mask', `url(#${part.id})`);
      if (reduced.matches || document.documentElement.classList.contains('motion-off')) { finish(); return; }
      playing = true; startedAt = null;
      marker.style.display = '';
      button.textContent = copy.pause;
      showProgress(elapsed / total);
      raf = requestAnimationFrame(tick);
    }
    button.addEventListener('click', () => {
      automaticPlayed = true; observer.disconnect();
      if (playing) {
        playing = false; cancelAnimationFrame(raf); raf = 0; startedAt = null;
        button.textContent = copy.resume;
      } else start();
    }, {signal});
    reduced.addEventListener('change', () => { if (playing && reduced.matches) { cancelAnimationFrame(raf); finish(); } }, {signal});
    const motionChange = new MutationObserver(() => {
      if (playing && document.documentElement.classList.contains('motion-off')) { cancelAnimationFrame(raf); finish(); }
    });
    motionChange.observe(document.documentElement, {attributes:true, attributeFilter:['class']});
    let automaticPlayed=false;
    const observer = new IntersectionObserver(entries => {
      if (automaticPlayed || !entries.some(entry => entry.isIntersecting)) return;
      automaticPlayed=true; observer.disconnect();
      if (!reduced.matches && !document.documentElement.classList.contains('motion-off')) start();
    }, {threshold:.18});
    observer.observe(canvas);

    dispose = () => {
      observer.disconnect(); motionChange.disconnect();
      playing = false;
      if (raf) cancelAnimationFrame(raf);
      controller.abort();
      parts.forEach(p => p.leg.removeAttribute('mask'));
      controls.remove(); marker.remove(); defs.remove();
      dispose = null;
    };
    window.addEventListener('pagehide', dispose, {once:true, signal});
  };
})();

